changeSet.sql:
CREATE OR REPLACE FUNCTION bng.reject_audit_log_mutation()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION
        'bng.audit_log is append-only; % is not permitted', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER audit_log_reject_row_mutation
    BEFORE UPDATE OR DELETE ON bng.audit_log
    FOR EACH ROW
    EXECUTE FUNCTION bng.reject_audit_log_mutation();

CREATE TRIGGER audit_log_reject_truncate
    BEFORE TRUNCATE ON bng.audit_log
    FOR EACH STATEMENT
    EXECUTE FUNCTION bng.reject_audit_log_mutation();

changeSet.rollback:
DROP TRIGGER IF EXISTS audit_log_reject_truncate ON bng.audit_log;
DROP TRIGGER IF EXISTS audit_log_reject_row_mutation ON bng.audit_log;
DROP FUNCTION IF EXISTS bng.reject_audit_log_mutation();
